def solve(payload):
    cpu = payload.get('cpu', 0)
    memory = payload.get('memory', 0)
    rows = sorted(payload.get('jobs', []), key=lambda row: (-row.get('priority', 0), row.get('id', '')))
    selected = []
    used_cpu = used_memory = priority = 0
    for row in rows:
        if used_cpu + row.get('cpu', 0) <= cpu and used_memory + row.get('memory', 0) <= memory:
            selected.append(row.get('id'))
            used_cpu += row.get('cpu', 0)
            used_memory += row.get('memory', 0)
            priority += row.get('priority', 0)
    return {'selected': sorted(selected), 'used': {'cpu': used_cpu, 'memory': used_memory}, 'priority': priority}

def solve(payload):
    rows = payload.get('jobs', [])
    cpu = payload.get('cpu', 0)
    memory = payload.get('memory', 0)
    best = []
    for row in rows:
        if row.get('cpu', 0) <= cpu and row.get('memory', 0) <= memory:
            best.append(row)
    best.sort(key=lambda row: (-row.get('priority', 0), row.get('id', '')))
    selected = [row.get('id') for row in best]
    return {'selected': sorted(selected), 'used': {'cpu': sum(row.get('cpu', 0) for row in best), 'memory': sum(row.get('memory', 0) for row in best)}, 'priority': sum(row.get('priority', 0) for row in best)}
